  "implementation": "def solve(case):
    payload = case['payload']
    nodes = payload['nodes']
    required_symbols = set(payload.get('required_symbols', []))
    node_map = {n['id']: n for n in nodes}
    child_map = {n['id']: [] for n in nodes}
    for n in nodes:
        p = n.get('parent')
        if p is not None:
            child_map.setdefault(p, []).append(n['id'])
    # validation: required symbols present
    symbols_in_nodes = {n['symbol'] for n in nodes}
    for sym in required_symbols:
        if sym not in symbols_in_nodes:
            raise ValueError(f'Required symbol {sym} not present in tree')
    retained = set(node_map.keys())
    candidates = []
    for nid, node in node_map.items():
        if (node['removable'] and node['symbol'] not in required_symbols
                and node['depth'] > 0):
            candidates.append((node['depth'], nid))
    candidates.sort(key=lambda x: (-x[0], x[1]))
    removal_order = []
    for depth, nid in candidates:
        if nid not in retained:
            continue
        node = node_map[nid]
        # check retained children
        has_retained_child = any(cid in retained for cid in child_map[nid])
        if has_retained_child:
            continue
        # check required symbols still present after removal
        counts = {}
        for rid in retained:
            if rid == nid:
                continue
            s = node_map[rid]['symbol']
            counts[s] = counts.get(s, 0) + 1
        feasible = True
        for sym in required_symbols:
            if counts.get(sym, 0) == 0:
                feasible = False
                break
        if not feasible:
            continue
        retained.remove(nid)
        removal_order.append(nid)
    retained_ids = sorted(retained)
    return {'retained_ids': retained_ids, 'removal_order': removal_order}"
